  teal2: '51B6AA',
  mint: 'DDF1EC',
  cream: 'F7F3EA',
  white: 'FFFFFF',
  sand: 'E9DFC9',
  rose: 'C95D63',
  gold: 'D9A441',
  plum: '674172',
  lavender: 'D8C9E8',
  gray: 'CBD3D9',
  darkGray: '394554'
};
