const FONT_B = 'Aptos';

function addBg(slide, color = C.cream) {
  slide.background = { color };
}
function addFooter(slide, n, dark=false) {
  slide.addText('Our World in Data / IHME Global Burden of Disease · World, 2023', {
    x: 0.55, y: 7.14, w: 8.6, h: 0.18, fontSize: 7.8, color: dark ? 'DDE7E8' : '6E7782', margin: 0, fit: 'shrink'
  });
