    x: 12.35, y: 7.03, w: 0.45, h: 0.28, fontSize: 9, bold: true, color: dark ? 'DDE7E8' : C.muted, align: 'right', margin: 0
  });
}
function addKicker(slide, text, dark=false) {
  slide.addShape(pptx.ShapeType.rect, { x: 0.6, y: 0.45, w: 0.12, h: 0.36, fill: { color: dark ? C.teal2 : C.teal }, line: { color: dark ? C.teal2 : C.teal } });
  slide.addText(text.toUpperCase(), { x: 0.82, y: 0.46, w: 5.5, h: 0.26, fontSize: 10, bold: true, charSpacing: 1.1, color: dark ? 'B8ECE6' : C.teal, margin: 0 });
}
function addTitle(slide, title, subtitle, dark=false) {
  addKicker(slide, 'Global mental health', dark);
  slide.addText(title, { x: 0.6, y: 0.95, w: 10.8, h: subtitle ? 0.82 : 1.05, fontFace: FONT_H, fontSize: 29, bold: true, color: dark ? C.white : C.ink, margin: 0, fit: 'shrink' });
  if (subtitle) slide.addText(subtitle, { x: 0.62, y: 1.74, w: 10.4, h: 0.48, fontSize: 13.2, color: dark ? 'DDE7E8' : C.muted, margin: 0, fit: 'shrink' });
}
function card(slide, x, y, w, h, fill=C.white, line='E4E1D8') {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.08, fill: { color: fill }, line: { color: line, transparency: 20 }, shadow: { type: 'outer', color: '000000', opacity: 0.09, blur: 2, angle: 45, offset: 1 } });
}
function sourceNote(slide, text, x=0.65, y=6.83, w=8.8, dark=false) {
  slide.addText(text, { x, y, w, h: 0.21, fontSize: 7.7, italic: true, color: dark ? 'BFD0D4' : '737B84', margin: 0, fit: 'shrink' });
}
function iconCircle(slide, x, y, label, color=C.teal, textColor=C.white, size=0.58) {
  slide.addShape(pptx.ShapeType.ellipse, { x, y, w: size, h: size, fill: { color }, line: { color, transparency: 100 } });
  slide.addText(label, { x, y: y+0.04, w: size, h: size*0.62, fontSize: size > 0.55 ? 17 : 12, bold: true, color: textColor, align: 'center', margin: 0, fit: 'shrink' });
}
function personIcon(slide, x, y, color, scale=1) {
  slide.addShape(pptx.ShapeType.ellipse, { x: x+0.07*scale, y, w: 0.16*scale, h: 0.16*scale, fill: { color }, line: { color } });
  slide.addShape(pptx.ShapeType.roundRect, { x, y: y+0.19*scale, w: 0.3*scale, h: 0.42*scale, rectRadius: 0.04, fill: { color }, line: { color } });
}
function addMiniPeople(slide, x, y, count, active, colorActive, label) {
  for (let i=0; i<count; i++) personIcon(slide, x + i*0.36, y, i < active ? colorActive : 'D5D1C7', 0.86);
  slide.addText(label, { x, y: y+0.72, w: count*0.36+0.4, h: 0.22, fontSize: 9.5, color: C.muted, align: 'center', margin: 0 });
}
function hBar(slide, x, y, w, h, value, max, color, label, valLabel, opts={}) {
  const labelW = opts.labelW || 2.35;
  const barX = x + labelW;
  const barW = w - labelW - 0.72;
  slide.addText(label, { x, y: y-0.03, w: labelW-0.15, h, fontSize: opts.fontSize || 12.5, bold: opts.bold || false, color: C.ink, align: 'right', margin: 0, fit: 'shrink' });
  slide.addShape(pptx.ShapeType.roundRect, { x: barX, y: y+0.05, w: barW, h: h-0.1, rectRadius: 0.04, fill: { color: 'E8E3D8' }, line: { color: 'E8E3D8' } });
  slide.addShape(pptx.ShapeType.roundRect, { x: barX, y: y+0.05, w: Math.max(0.05, barW*value/max), h: h-0.1, rectRadius: 0.04, fill: { color }, line: { color } });
  slide.addText(valLabel, { x: barX+barW+0.14, y: y-0.01, w: 0.58, h, fontSize: opts.valSize || 11.2, bold: true, color: C.ink, margin: 0 });
}
function vBar(slide, x, yBase, w, hMax, value, max, color, label, valueText) {
  const h = hMax*value/max;
  slide.addShape(pptx.ShapeType.roundRect, { x, y: yBase-h, w, h, rectRadius: 0.06, fill: { color }, line: { color } });
  slide.addText(valueText, { x: x-0.07, y: yBase-h-0.42, w: w+0.14, h: 0.28, fontSize: 16, bold: true, color, align: 'center', margin: 0 });
  slide.addText(label, { x: x-0.34, y: yBase+0.14, w: w+0.68, h: 0.35, fontSize: 11.5, bold: true, color: C.ink, align: 'center', margin: 0, fit: 'shrink' });
}

// Slide 1
{
