  slide.addText('Prevalence, Impact, and the Treatment Gap', { x: 0.82, y: 2.94, w: 7.8, h: 0.42, fontSize: 18, color: 'DDE7E8', margin: 0 });
  slide.addText('A data-driven overview of global mental health conditions, their disease burden, and the persistent gap between need and treatment.', { x: 0.82, y: 3.62, w: 6.75, h: 0.72, fontSize: 14.5, color: 'C7D8DC', margin: 0.02, breakLine: false, fit: 'shrink' });
  card(slide, 8.08, 4.88, 4.38, 1.15, '213153', '2D4468');
  slide.addText('Global data · 2023', { x: 8.35, y: 5.11, w: 2.3, h: 0.28, fontSize: 17, bold: true, color: C.white, margin: 0 });
  slide.addText('Our World in Data / IHME', { x: 8.36, y: 5.49, w: 2.6, h: 0.22, fontSize: 10.2, color: 'BFD0D4', margin: 0 });
  iconCircle(slide, 11.36, 5.13, 'GBD', C.teal2, C.navy, 0.58);
