  vBar(slide, 2.15, 5.65, 1.28, 2.85, 694.6, 720, C.rose, 'Depressive\ndisorders', '694.6');
  vBar(slide, 5.1, 5.65, 1.28, 2.85, 686.5, 720, C.teal, 'Anxiety\ndisorders', '686.5');
